// HSI_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module HSI_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [7:0] c_cfg_div,
  input logic [2:0] c_cfg_chbits,
  input logic  c_cfg_rx_en,
  input logic  c_cfg_wake,
  input logic [3:0] c_txq_ch,
  input logic [31:0] c_txq_data,
  input logic [3:0] c_rxq_ch,
  input logic [31:0] c_rxq_data,
  input logic  c_tx_brk,
  input logic  c_tx_busy,
  input logic  c_txq_valid,
  input logic  c_txq_ready,
  input logic  c_rxq_valid,
  input logic  c_rxq_ready,
  input logic  c_tx_done,
  input logic  c_rx_break,
  input logic  c_err_overflow,
  input logic  c_err_stray,
  input logic  c_err_ds,
  input logic  c_err_timeout
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 12;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:11];          // model of every stored word
  logic [8:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_TX;          // full / valid pulse / available
  logic m_state_RX;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_tx_done) m_set[0] = 1'b1;
    if (c_rx_break) m_set[1] = 1'b1;
    if (c_err_overflow) m_set[2] = 1'b1;
    if (c_err_stray) m_set[3] = 1'b1;
    if (c_err_ds) m_set[4] = 1'b1;
    if (c_err_timeout) m_set[5] = 1'b1;
    if (m_state_TX && c_txq_ready) m_set[6] = 1'b1;
    if (m_wr && m_map && (m_idx == 6 || m_idx == 7) && m_state_TX) m_set[7] = 1'b1;
    if (c_rxq_valid && !m_state_RX) m_set[8] = 1'b1;
    if (c_rxq_valid && m_state_RX && (m_rd && m_map && m_idx == 9)) m_set[8] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'hC07;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_TX <= 0;
      m_state_RX <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1FF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h1FFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 10) ? PWDATA & m_be & 32'h1 : 0;
      if (m_wr && m_map && m_idx == 6 && !m_state_TX) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      if (m_wr && m_map && m_idx == 7 && !m_state_TX) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7 && !m_state_TX) m_state_TX <= 1;
      if (m_state_TX && c_txq_ready) m_state_TX <= 0;
      if (c_rxq_valid && (!m_state_RX || (m_rd && m_map && m_idx == 9))) begin
        m_w[8] <= (32'(c_rxq_ch[3:0]) << 0);
        m_w[9] <= (32'(c_rxq_data[31:0]) << 0);
        m_state_RX <= 1;
      end else if ((m_rd && m_map && m_idx == 9)) m_state_RX <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h48530200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_RX, m_state_TX});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return 0;
      11: return (32'(c_tx_busy) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][8:0] & m_w[2][8:0]))
  `SVA_INV(a_core_cfg_div, c_cfg_div == m_w[5][7:0])
  `SVA_INV(a_core_cfg_chbits, c_cfg_chbits == m_w[5][10:8])
  `SVA_INV(a_core_cfg_rx_en, c_cfg_rx_en == m_w[5][11:11])
  `SVA_INV(a_core_cfg_wake, c_cfg_wake == m_w[5][12:12])
  `SVA_INV(a_core_txq_ch, c_txq_ch == m_w[6][3:0])
  `SVA_INV(a_core_txq_data, c_txq_data == m_w[7][31:0])
  `SVA_INV(a_core_tx_brk, c_tx_brk == m_pulse_CMD[0])
  `SVA_INV(a_core_txq_valid, c_txq_valid == m_state_TX)
  `SVA_INV(a_core_rxq_ready, c_rxq_ready == (!m_state_RX || (m_rd && m_map && m_idx == 9)))
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_div == 8'h7 && c_cfg_chbits == 3'h4 && c_cfg_rx_en == 1'h1 && c_cfg_wake == 1'h0 && c_txq_ch == 4'h0 && c_txq_data == 32'h0 && c_tx_brk == 1'h0 && !c_txq_valid && c_rxq_ready)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CFG, m_rd && m_map && m_idx == 5)
  `FC(wr_CFG, m_wr && m_map && m_idx == 5)
  `FC(rd_TX0, m_rd && m_map && m_idx == 6)
  `FC(wr_TX0, m_wr && m_map && m_idx == 6)
  `FC(rd_TX1, m_rd && m_map && m_idx == 7)
  `FC(wr_TX1, m_wr && m_map && m_idx == 7)
  `FC(rd_RX0, m_rd && m_map && m_idx == 8)
  `FC(wr_RX0, m_wr && m_map && m_idx == 8)
  `FC(rd_RX1, m_rd && m_map && m_idx == 9)
  `FC(wr_RX1, m_wr && m_map && m_idx == 9)
  `FC(rd_CMD, m_rd && m_map && m_idx == 10)
  `FC(wr_CMD, m_wr && m_map && m_idx == 10)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 11)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 11)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_TX_SENT_set, m_set[0])
  `FC(irq_TX_SENT_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_TX_SENT_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_TX_SENT_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_RX_BREAK_set, m_set[1])
  `FC(irq_RX_BREAK_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_RX_BREAK_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_RX_BREAK_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_ERR_OVERFLOW_set, m_set[2])
  `FC(irq_ERR_OVERFLOW_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_ERR_OVERFLOW_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_ERR_OVERFLOW_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_ERR_STRAY_set, m_set[3])
  `FC(irq_ERR_STRAY_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_ERR_STRAY_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_ERR_STRAY_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_ERR_DS_set, m_set[4])
  `FC(irq_ERR_DS_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_ERR_DS_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_ERR_DS_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_ERR_TIMEOUT_set, m_set[5])
  `FC(irq_ERR_TIMEOUT_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_ERR_TIMEOUT_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_ERR_TIMEOUT_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_TX_DONE_set, m_set[6])
  `FC(irq_TX_DONE_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_TX_DONE_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_TX_DONE_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(irq_TX_OVF_set, m_set[7])
  `FC(irq_TX_OVF_cleared, m_w[1][7] && m_wr && m_map && m_idx == 1 && PWDATA[7] && PSTRB[0])
  `FC(irq_TX_OVF_masked, m_w[1][7] && !m_w[2][7])
  `FC(irq_TX_OVF_drives_pin, m_w[1][7] && m_w[2][7] && irq)
  `FC(irq_RX_AVAIL_set, m_set[8])
  `FC(irq_RX_AVAIL_cleared, m_w[1][8] && m_wr && m_map && m_idx == 1 && PWDATA[8] && PSTRB[1])
  `FC(irq_RX_AVAIL_masked, m_w[1][8] && !m_w[2][8])
  `FC(irq_RX_AVAIL_drives_pin, m_w[1][8] && m_w[2][8] && irq)
  `FC(cmd_tx_brk, m_pulse_CMD[0])
  `FC(TX_handshake, m_state_TX && c_txq_ready)
  `FC(TX_backpressure, m_state_TX && !c_txq_ready)
  `FC(TX_write_while_full, m_wr && m_map && m_idx == 7 && m_state_TX)
  `FC(RX_capture, c_rxq_valid && !m_state_RX)
  `FC(RX_backpressure, c_rxq_valid && m_state_RX && !(m_rd && m_map && m_idx == 9))
  `FC(RX_pop, m_rd && m_map && m_idx == 9 && m_state_RX)
  `FC(RX_read_empty, m_rd && m_map && m_idx == 9 && !m_state_RX)
  `FC(RX_pop_and_capture, c_rxq_valid && m_state_RX && m_rd && m_map && m_idx == 9)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind HSI_apb HSI_apb_sva u_apb_sva (.*);
